async function api(url,options={}){const response=await fetch(url,{credentials:'same-origin',...options,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(options.headers||{})}});const type=response.headers.get('content-type')||'';const data=type.includes('application/json')?await response.json():await response.text();if(!response.ok){if(response.status===503&&data&&data.code==='RESOURCE_TEMPORARILY_UNAVAILABLE')showToast('Resource temporarily unavailable');if(response.status===401&&data&&data.forcedLogout){currentUser=null;terminateApp('Session ended by host memory protection');$('desktop-view').classList.add('hidden');$('login-view').classList.remove('hidden');$('login-error').textContent=data.error||'Your computer was forcibly logged out because of a problem.';}throw new Error(data?.error||`Request failed (${response.status})`);}return data;}
