function projectTypeLabel(type){return ({'standard-app':'Standard App Project','daemon':'Daemon Project','layer1':'Layer 1 Application / Daemon Project','installer':'Installer Project'})[type]||type;}
function actionButton(label,fn,cls='secondary'){const b=document.createElement('button');b.type='button';b.className=cls;b.textContent=label;b.addEventListener('click',fn);return b;}
