async function loadControl(){try{await loadRuntimePolicy();await loadResistPreference();const s=await api('/api/server/status');$('control-summary').textContent=`Server ${s.status} · Port ${s.port} · Uptime ${s.uptime}s`;$('server-port').value=s.port;if(currentUser.role==='admin'){$('admin-tools').classList.remove('hidden');const d=await api('/api/users');const box=$('users-table');box.replaceChildren();for(const u of d.users){const row=document.createElement('div');row.className='row';row.style.justifyContent='space-between';const label=document.createElement('span');label.textContent=u.username+' · '+u.role;row.append(label);const capLabel=document.createElement('label');capLabel.className='row';capLabel.style.gap='6px';const cap=document.createElement('input');cap.type='checkbox';cap.checked=u.removeRamCap===true;cap.title='Remove RAM Cap for this user';cap.addEventListener('change',async()=>{try{await api('/api/users/'+encodeURIComponent(u.username)+'/memory-cap',{method:'PATCH',body:JSON.stringify({removeRamCap:cap.checked})});showToast((cap.checked?'Removed':'Restored')+' RAM cap for '+u.username);}catch(e){cap.checked=!cap.checked;showToast(e.message);}});const capText=document.createElement('span');capText.textContent='Remove RAM Cap';capLabel.append(cap,capText);row.append(capLabel);if(u.username!==currentUser.username){const role=actionButton(u.role==='admin'?'Demote':'Promote',async()=>{await api('/api/users/'+encodeURIComponent(u.username)+'/role',{method:'PATCH',body:JSON.stringify({role:u.role==='admin'?'user':'admin'})});loadControl();});const del=actionButton('Delete',async()=>{if(confirm('Delete '+u.username+' and their home directory?')){await api('/api/users/'+encodeURIComponent(u.username),{method:'DELETE'});loadControl();}},'danger');row.append(role,del);}box.append(row);}const layer1Data=await api('/api/layer1/pending');const layer1Box=$('layer1-pending-list');layer1Box.replaceChildren();for(const item of layer1Data.pending){const row=document.createElement('div');row.className='row';row.style.justifyContent='space-between';const label=document.createElement('span');label.textContent=item.name+' · '+item.id+' · '+item.version+' · pending';row.append(label,actionButton('Reject',async()=>{if(confirm('Remove pending package '+item.id+'?')){await api('/api/layer1/pending/'+encodeURIComponent(item.id),{method:'DELETE'});loadControl();}},'danger'));layer1Box.append(row);}const daemonData=await api('/api/daemons');const daemonBox=$('daemon-list');daemonBox.replaceChildren();for(const daemon of daemonData.daemons){const row=document.createElement('div');row.className='row';row.style.justifyContent='space-between';const label=document.createElement('span');label.textContent=daemon.name+' · '+daemon.id+' · '+daemon.state+(daemon.enabled?' · enabled':' · disabled');row.append(label);for(const action of ['start','stop','enable','disable'])row.append(actionButton(action,async()=>{try{await api('/api/daemons/'+action,{method:'POST',body:JSON.stringify({id:daemon.id})});$('daemon-message').textContent=action+' completed for '+daemon.id;loadControl();}catch(e){$('daemon-message').textContent=e.message;}},'secondary'));daemonBox.append(row);}}}catch(e){$('control-summary').textContent=e.message;}}
