async function loadIDE(){try{const d=await api('/api/ide/templates');ideTemplates=d.templates;const select=$('ide-template');if(!select.options.length){for(const t of ideTemplates){const o=document.createElement('option');o.value=t.id;o.textContent=t.title+' · '+projectTypeLabel(t.type);select.append(o);}if(ideTemplates[0])$('ide-project-name').value=ideTemplates[0].title;select.addEventListener('change',()=>{const t=ideTemplates.find(x=>x.id===select.value);if(t)$('ide-project-name').value=t.title;});}const cards=$('ide-examples');cards.replaceChildren();for(const t of ideTemplates){const card=document.createElement('div');card.className='template-card';const title=document.createElement('strong');title.textContent=t.title+' · '+projectTypeLabel(t.type);const desc=document.createElement('p');desc.textContent=t.description;const use=actionButton('Use example',()=>{select.value=t.id;$('ide-project-name').value=t.title;},'secondary');card.append(title,desc,use);cards.append(card);}}catch(e){$('ide-message').textContent=e.message;}}
