async function loadIDEProject(){const path=$('ide-project-path').value.trim();if(!path){$('ide-message').textContent='Enter a project path.';return;}try{const d=await api('/api/ide/project?path='+encodeURIComponent(path));ideProjectPath=d.path;ideCurrentFile='';ideManifest=null;const manifestFile=await api('/api/files/content?path='+encodeURIComponent(ideProjectPath+'/aetheros.project.json'));ideManifest=JSON.parse(manifestFile.content);ideProjectType=ideManifest.type;$('installer-drop').classList.toggle('hidden',ideProjectType!=='installer');$('ide-compile').disabled=false;$('ide-save-file').disabled=true;$('ide-editor-content').value='';$('ide-editor-content').disabled=true;$('ide-editor-title').textContent='Select a source file';const list=$('ide-file-list');list.replaceChildren();for(const file of d.files){const b=actionButton(file.path.slice(ideProjectPath.length+1),()=>openIDEFile(file.path),'secondary');b.classList.add('ide-file-item');list.append(b);}if(!d.files.length)list.textContent='No files in project.';$('ide-message').textContent=d.files.length+' project files loaded.';}catch(e){$('ide-message').textContent=e.message;}}
$('ide-new-file').addEventListener('click',async()=>{if(!ideProjectPath)return;const name=prompt('New file path inside this project (e.g. src/app.js):');if(!name)return;const clean=name.replace(/\\/g,'/').replace(/^\/+|\/+$/g,'');if(!clean||clean.split('/').includes('..')){$('ide-message').textContent='Invalid project file path.';return;}const full=ideProjectPath+'/'+clean;try{await api('/api/files/file',{method:'POST',body:JSON.stringify({path:full,content:''})});await loadIDEProject();await openIDEFile(full);}catch(e){$('ide-message').textContent=e.message;}});
async function openIDEFile(path){try{if(!/\.(html?|js|mjs|cjs|css|json|md|txt|xml|svg|yml|yaml|toml)$/i.test(path))throw new Error('This looks like a binary asset. It remains part of the project and will be included in the build, but is not editable in the text editor.');const d=await api('/api/files/content?path='+encodeURIComponent(path));ideCurrentFile=path;$('ide-editor-title').textContent=path;$('ide-editor-content').value=d.content;$('ide-editor-content').disabled=false;$('ide-save-file').disabled=false;}catch(e){$('ide-message').textContent=e.message;}}
$('ide-save-file').addEventListener('click',async()=>{if(!ideCurrentFile)return;try{await api('/api/files/content',{method:'PUT',body:JSON.stringify({path:ideCurrentFile,content:$('ide-editor-content').value})});$('ide-message').textContent='Saved '+ideCurrentFile;}catch(e){$('ide-message').textContent=e.message;}});
async function attachInstallerPayload(file){if(!ideProjectPath||ideProjectType!=='installer')throw new Error('Load an Installer Project first.');if(!file||!file.name.toLowerCase().endsWith('.aoapp'))throw new Error('Choose a compiled .aoapp package (app, daemon or Layer 1).');if(file.size>20*1024*1024)throw new Error('AOAPP package exceeds 20 MiB.');const safeName=file.name.replace(/[^a-zA-Z0-9._-]/g,'-').slice(-100);const packagePath='Packages/'+Date.now()+'-'+safeName;const response=await fetch('/api/files/blob?path='+encodeURIComponent(packagePath),{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/octet-stream'},body:file});const result=await response.json();if(!response.ok)throw new Error(result.error||'Package upload failed.');const configPath=ideProjectPath+'/'+(ideManifest.entrypoint||'installer.json');const configData=await api('/api/files/content?path='+encodeURIComponent(configPath));const installerConfig=JSON.parse(configData.content);installerConfig.packagePath=packagePath;const updated=JSON.stringify(installerConfig,null,2)+'\n';await api('/api/files/content',{method:'PUT',body:JSON.stringify({path:configPath,content:updated})});if(ideCurrentFile===configPath)$('ide-editor-content').value=updated;$('ide-message').textContent='Attached '+file.name+' · '+packagePath;await loadIDEProject();}
const installerDrop=$('installer-drop');installerDrop.addEventListener('dragover',e=>{if(ideProjectType==='installer'){e.preventDefault();installerDrop.classList.add('dragging');}});installerDrop.addEventListener('dragleave',()=>installerDrop.classList.remove('dragging'));installerDrop.addEventListener('drop',async e=>{e.preventDefault();installerDrop.classList.remove('dragging');try{await attachInstallerPayload(e.dataTransfer.files[0]);}catch(err){$('ide-message').textContent=err.message;}});$('installer-file').addEventListener('change',async e=>{try{if(e.target.files[0])await attachInstallerPayload(e.target.files[0]);}catch(err){$('ide-message').textContent=err.message;}finally{e.target.value='';}});
$('ide-compile').addEventListener('click',async()=>{if(!ideProjectPath)return;try{const d=await api('/api/ide/compile',{method:'POST',body:JSON.stringify({path:ideProjectPath})});const box=$('ide-build-result');box.classList.remove('hidden');box.replaceChildren();const title=document.createElement('strong');title.textContent='Build successful · '+d.type;const detail=document.createElement('p');detail.textContent=d.path+' · '+d.bytes.toLocaleString()+' bytes · '+d.trust;const download=document.createElement('a');download.href='/api/files/download?path='+encodeURIComponent(d.path);download.textContent='Download '+d.path.split('/').pop();download.className='secondary';box.append(title,detail,download);if(d.type==='standard-app'){box.append(document.createTextNode(' '),actionButton('Run package',()=>launchApp(d.path)));}else if(d.type==='installer'){const note=document.createElement('p');note.textContent='Installer built. Open it in File Manager and choose Install.';box.append(note);}else{const note=document.createElement('p');note.textContent=d.type==='daemon'?'Daemon package built. Install its .aoi installer, then manage it with aetherctl.':'Layer 1 package built. Installation stages it for privileged review; it is not executed by Webtop.';box.append(note);}$('ide-message').textContent='Compiled successfully.';}catch(e){$('ide-message').textContent='Build failed: '+e.message;}});

function browserId(){return (window.crypto&&crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random().toString(36).slice(2)).replace(/[^a-zA-Z0-9_-]/g,'').slice(0,48);}
function activeBrowserTab(){return browserState.tabs.find(t=>t.id===browserState.activeId)||null;}
function browserSafeUrl(value){let raw=String(value||'').trim();if(!raw)return null;if(!/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(raw))raw='https://'+raw;try{const u=new URL(raw);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)return null;return u.href;}catch{return null;}}
async function persistBrowser(){try{await api('/api/browser/state',{method:'PUT',body:JSON.stringify(browserState)});}catch(e){$('browser-message').textContent='Could not save browser workspace: '+e.message;}}
function renderBrowser(){const groups=$('browser-groups'),tabs=$('browser-tabs');groups.replaceChildren();const all=document.createElement('button');all.className='browser-group'+(browserActiveGroup===null?' active':'');all.textContent='All tabs';all.addEventListener('click',()=>{browserActiveGroup=null;renderBrowser();});groups.append(all);for(const group of browserState.groups){const b=document.createElement('button');b.className='browser-group'+(browserActiveGroup===group.id?' active':'');b.dataset.color=group.color;b.textContent=group.name;b.title='Click to move the active tab into this group';b.addEventListener('click',async()=>{const tab=activeBrowserTab();if(tab){tab.groupId=group.id;browserActiveGroup=group.id;await persistBrowser();renderBrowser();}});groups.append(b);}const ungroup=document.createElement('button');ungroup.className='browser-group';ungroup.textContent='Ungroup active';ungroup.addEventListener('click',async()=>{const tab=activeBrowserTab();if(tab){tab.groupId=null;browserActiveGroup=null;await persistBrowser();renderBrowser();}});groups.append(ungroup);
tabs.replaceChildren();const visible=browserState.tabs.filter(t=>browserActiveGroup===null||t.groupId===browserActiveGroup);if(!visible.length){const empty=document.createElement('span');empty.className='muted';empty.textContent='No tabs in this group';tabs.append(empty);}for(const tab of visible){const b=document.createElement('div');b.className='browser-tab'+(tab.id===browserState.activeId?' active':'');b.setAttribute('role','tab');b.setAttribute('aria-selected',String(tab.id===browserState.activeId));const label=document.createElement('span');label.textContent=tab.title||new URL(tab.url).hostname;label.title=tab.url;label.addEventListener('click',()=>activateBrowserTab(tab.id));const close=document.createElement('button');close.type='button';close.textContent='×';close.title='Close tab';close.addEventListener('click',e=>{e.stopPropagation();closeBrowserTab(tab.id);});b.append(label,close);b.addEventListener('click',()=>activateBrowserTab(tab.id));tabs.append(b);}const active=activeBrowserTab();$('browser-address').value=active?.url||'';$('browser-back').disabled=!active||active.historyIndex<=0;$('browser-forward').disabled=!active||active.historyIndex>=active.history.length-1;}
function activateBrowserTab(id){const tab=browserState.tabs.find(t=>t.id===id);if(!tab)return;browserState.activeId=id;if(tab.groupId)browserActiveGroup=tab.groupId;else browserActiveGroup=null;$('browser-frame').src=tab.url;renderBrowser();persistBrowser();}
async function loadBrowser(){try{if(!('credentialless' in HTMLIFrameElement.prototype)){$('browser-message').textContent='This browser does not support credentialless frames. External browsing is disabled to protect account isolation.';$('browser-frame').src='about:blank';return;} $('browser-frame').credentialless=true;browserState=await api('/api/browser/state');if(!browserState.tabs.length){const tab={id:browserId(),url:'https://example.com/',title:'New tab',groupId:null};browserState.tabs.push(tab);browserState.activeId=tab.id;await persistBrowser();}renderBrowser();const active=activeBrowserTab();if(active)$('browser-frame').src=active.url;}catch(e){$('browser-message').textContent='Browser workspace unavailable: '+e.message;}}
async function newBrowserTab(url='https://example.com/'){if(browserState.tabs.length>=50){$('browser-message').textContent='Maximum of 50 open tabs.';return;}const tab={id:browserId(),url,title:'New tab',groupId:browserActiveGroup,history:[url],historyIndex:0};browserState.tabs.push(tab);browserState.activeId=tab.id;activateBrowserTab(tab.id);}
async function closeBrowserTab(id){const index=browserState.tabs.findIndex(t=>t.id===id);if(index<0)return;browserState.tabs.splice(index,1);if(browserState.activeId===id){const next=browserState.tabs[Math.min(index,browserState.tabs.length-1)];browserState.activeId=next?.id||null;if(next)$('browser-frame').src=next.url;else $('browser-frame').src='about:blank';}renderBrowser();await persistBrowser();}
$('browser-new-tab').addEventListener('click',()=>newBrowserTab());$('browser-new-group').addEventListener('click',async()=>{if(browserState.groups.length>=20){$('browser-message').textContent='Maximum of 20 tab groups.';return;}const name=prompt('Name this tab group:');if(!name||!name.trim())return;const colors=['blue','green','purple','orange','red','grey'];const group={id:browserId(),name:name.trim().slice(0,40),color:colors[browserState.groups.length%colors.length]};browserState.groups.push(group);browserActiveGroup=group.id;const tab=activeBrowserTab();if(tab)tab.groupId=group.id;await persistBrowser();renderBrowser();});
$('browser-address-form').addEventListener('submit',async e=>{e.preventDefault();const url=browserSafeUrl($('browser-address').value);if(!url){$('browser-message').textContent='Only valid HTTP and HTTPS addresses are supported.';return;}let tab=activeBrowserTab();if(!tab){await newBrowserTab(url);return;}tab.url=url;tab.title=new URL(url).hostname;tab.history=Array.isArray(tab.history)?tab.history.slice(0,tab.historyIndex+1):[];if(tab.history[tab.history.length-1]!==url)tab.history.push(url);if(tab.history.length>50)tab.history.shift();tab.historyIndex=tab.history.length-1;$('browser-frame').src=url;$('browser-message').textContent='Opened '+url+' in an isolated tab.';renderBrowser();await persistBrowser();});$('browser-reload').addEventListener('click',()=>{const tab=activeBrowserTab();if(tab)$('browser-frame').src=tab.url;});$('browser-back').addEventListener('click',async()=>{const tab=activeBrowserTab();if(!tab||tab.historyIndex<=0)return;tab.historyIndex--;tab.url=tab.history[tab.historyIndex];$('browser-frame').src=tab.url;renderBrowser();await persistBrowser();});$('browser-forward').addEventListener('click',async()=>{const tab=activeBrowserTab();if(!tab||tab.historyIndex>=tab.history.length-1)return;tab.historyIndex++;tab.url=tab.history[tab.historyIndex];$('browser-frame').src=tab.url;renderBrowser();await persistBrowser();});

checkSession();window.setInterval(()=>{if(currentUser)api('/api/auth/me').catch(()=>{});},15000);
